using System;using System.IO;using System.Drawing;using System.Threading.Tasks;using System.Windows.Forms;using NAudio.Wave;
namespace Captura {
 static class AvTests {
  static void Tone(string path,double frequency,double seconds){using(var writer=new WaveFileWriter(path,new WaveFormat(48000,16,1))){byte[] bytes=new byte[(int)(seconds*48000)*2];for(int i=0;i<bytes.Length/2;i++){short sample=(short)(Math.Sin(i*2*Math.PI*frequency/48000)*5000);bytes[i*2]=(byte)sample;bytes[i*2+1]=(byte)(sample>>8);}writer.Write(bytes,0,bytes.Length);}}
  public static void Run(){string log=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"av-test.txt");string dir=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"av-tests-"+DateTime.Now.ToString("yyyyMMdd-HHmmss"));Directory.CreateDirectory(dir);File.WriteAllText(log,"");using(var fixture=new Form{Text="Priint AV TEST",ClientSize=new Size(640,360),Location=new Point(60,60),StartPosition=FormStartPosition.Manual,BackColor=Color.Navy}){fixture.Shown+=async delegate{try{fixture.Hide();fixture.Show();Application.DoEvents();string ff=EncoderLocator.Find();
    using(var feed=new CameraFeed()){await Task.Run(()=>feed.Start(ff,null,true));if(!feed.IsReady)throw new Exception("Câmera sintética sem imagem");File.AppendAllText(log,"CameraFeed sintético pronto; detector nativo="+feed.TrackingAvailable+Environment.NewLine);if(!feed.TrackingAvailable)throw new Exception("Modelo de enquadramento indisponível");
     using(var recorder=new RecordingEngine()){var req=new RecordingRequest{Mode=RecordingMode.Monitor,Region=new Rectangle(fixture.Left+10,fixture.Top+40,320,180),EncoderPath=ff,OutputDirectory=dir,Fps=30,Camera=feed,CameraBounds=new Rectangle(180,70,110,110),CameraShape="Redonda",CameraZoom=1.4f};recorder.Start(req);await Task.Delay(700);recorder.Pause();await Task.Delay(600);if(!recorder.IsPaused)throw new Exception("Pausa não aplicada");recorder.Resume();await Task.Delay(700);string video=await recorder.StopAsync();File.AppendAllText(log,"Câmera compartilhada + redonda + zoom + pausa/retomada: "+video+Environment.NewLine);}
    }
    using(var fast=new CameraFeed()){await Task.Run(()=>fast.Start(ff,null,true,60));fast.Tracking=true;await Task.Delay(1000);long begin=fast.FramesReceived;var watch=System.Diagnostics.Stopwatch.StartNew();using(var canvas=new Bitmap(320,240))using(var graphics=Graphics.FromImage(canvas)){while(watch.ElapsedMilliseconds<2500){fast.DrawLatest(graphics,new Rectangle(0,0,320,240),"Redonda",1,false,true);await Task.Delay(80);}}double rate=(fast.FramesReceived-begin)/watch.Elapsed.TotalSeconds;File.AppendAllText(log,"Camera 60fps com consumidor lento e tracking: "+rate.ToString("F1")+" fps; idade="+fast.FrameAgeMs.ToString("F0")+"ms"+Environment.NewLine);if(rate<40||fast.FrameAgeMs>250)throw new Exception("Camera acumulando atraso");if(CameraFeed.CaptureArguments("virtual",false,60).Contains("-r 15"))throw new Exception("Limite antigo presente");}
    using(var source=new Bitmap(200,100))using(var result=new Bitmap(200,120)){using(var g=Graphics.FromImage(source)){g.Clear(Color.Red);g.FillRectangle(Brushes.Lime,0,0,100,100);}using(var g=Graphics.FromImage(result)){g.Clear(Color.Blue);CameraDraw.Draw(g,source,new Rectangle(10,10,80,80),"Redonda",1,false,new PointF(.5f,.5f));}if(result.GetPixel(10,10).ToArgb()!=Color.Blue.ToArgb()||result.GetPixel(50,50).ToArgb()==Color.Blue.ToArgb())throw new Exception("Máscara redonda incorreta");}
    string face=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"face-fixture.jpg");if(File.Exists(face)){using(var c=new OpenCvSharp.CascadeClassifier(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"haarcascade_frontalface_default.xml")))using(var image=OpenCvSharp.Cv2.ImRead(face,OpenCvSharp.ImreadModes.Grayscale)){if(c.DetectMultiScale(image,1.15,4).Length<1)throw new Exception("Detecção de rosto na fixture falhou");}File.AppendAllText(log,"Detecção de rosto em fixture pública: OK"+Environment.NewLine);}
    foreach(int tracks in new[]{1,2}){var files=new string[tracks];for(int i=0;i<tracks;i++){files[i]=Path.Combine(dir,"audio-"+tracks+"-"+i+".wav");Tone(files[i],440+i*200,1.8);}using(var recorder=new RecordingEngine()){recorder.Start(new RecordingRequest{Mode=RecordingMode.Region,Region=new Rectangle(fixture.Left+10,fixture.Top+40,320,180),EncoderPath=ff,OutputDirectory=dir,Fps=30,TestAudioTracks=files});await Task.Delay(1500);string video=await recorder.StopAsync();File.AppendAllText(log,"Mux "+tracks+" faixa(s) áudio: "+video+Environment.NewLine);}}
    var outputs=AudioDevices.List(true);var inputs=AudioDevices.List(false);File.AppendAllText(log,"Enumeração WASAPI: "+outputs.Count+" saídas; "+inputs.Count+" entradas (sem abrir captura física)."+Environment.NewLine);
    fixture.TopMost=true;fixture.BringToFront();fixture.Activate();fixture.Refresh();Application.DoEvents();await Task.Delay(200);using(var hud=new RecordingHud()){hud.Location=new Point(fixture.Left+100,fixture.Top+100);Color baseline;using(var before=new Bitmap(20,20)){using(var g=Graphics.FromImage(before))g.CopyFromScreen(hud.Left+11,hud.Top+8,0,0,before.Size);baseline=before.GetPixel(8,8);}hud.Show();hud.State("Gravando");Application.DoEvents();await Task.Delay(600);using(var shot=new Bitmap(20,20)){using(var g=Graphics.FromImage(shot))g.CopyFromScreen(hud.Left+11,hud.Top+8,0,0,shot.Size);bool green=false;for(int x=0;x<20;x++)for(int y=0;y<20;y++){var c=shot.GetPixel(x,y);if(c.G>80&&c.G>c.B*1.5&&c.G>c.R)green=true;}if(green)throw new Exception("Indicador apareceu na captura!");File.AppendAllText(log,"HUD baseline="+baseline+" sample="+shot.GetPixel(8,8)+Environment.NewLine);if(hud.Excluded&&shot.GetPixel(8,8).ToArgb()!=baseline.ToArgb())throw new Exception("Indicador deixou retângulo na captura.");}File.AppendAllText(log,"Indicador: WDA_EXCLUDEFROMCAPTURE="+hud.Excluded+"; nenhum ponto verde capturado."+Environment.NewLine);hud.Hide();}
    File.AppendAllText(log,"OK AV pipeline, pausa, máscara, detector, áudio digital, enumeração e indicador."+Environment.NewLine);
   }catch(Exception ex){File.AppendAllText(log,"FAIL "+ex+Environment.NewLine);Environment.ExitCode=1;}finally{fixture.Close();}};fixture.ShowDialog();}}
 }
}


